/**
 * @summary Complete a run; server rolls loot and settles the economy
 */
export const CompleteRunParams = zod.object({
  "id": zod.coerce.number()
})


export const completeRunBodyEnemiesDefeatedMin = 0;

export const completeRunBodyNodesHarvestedMin = 0;

export const completeRunBodyChestsOpenedMin = 0;

export const completeRunBodyTimeSecondsMin = 0;

export const completeRunBodyDamageTakenMin = 0;



export const CompleteRunBody = zod.object({
  "idempotencyKey": zod.string().min(1),
  "cleared": zod.boolean(),
  "enemiesDefeated": zod.number().min(completeRunBodyEnemiesDefeatedMin),
  "nodesHarvested": zod.number().min(completeRunBodyNodesHarvestedMin),
  "chestsOpened": zod.number().min(completeRunBodyChestsOpenedMin),
  "bossDefeated": zod.boolean(),
  "timeSeconds": zod.number().min(completeRunBodyTimeSecondsMin),
  "damageTaken": zod.number().min(completeRunBodyDamageTakenMin).optional()
})

